CREATE OR REPLACE FUNCTION public.guard_removal() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.admin_removed AND NOT NEW.admin_removed THEN RAISE EXCEPTION 'Cannot restore moderation removal'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND NEW.admin_removed IS DISTINCT FROM OLD.admin_removed THEN RAISE EXCEPTION 'Admin only'; END IF; IF TG_TABLE_NAME='posts' THEN IF OLD.author_deleted AND NOT NEW.author_deleted THEN RAISE EXCEPTION 'Cannot restore deleted post'; END IF; IF NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.pseudonym IS DISTINCT FROM OLD.pseudonym OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN RAISE EXCEPTION 'Protected fields'; END IF; IF NOT public.has_role(auth.uid(),'admin') AND (NEW.title IS DISTINCT FROM OLD.title OR NEW.body IS DISTINCT FROM OLD.body OR NEW.community IS DISTINCT FROM OLD.community OR NEW.post_type IS DISTINCT FROM OLD.post_type OR NEW.expires_at IS DISTINCT FROM OLD.expires_at) THEN RAISE EXCEPTION 'Protected fields'; END IF; ELSE IF NEW.author_id IS DISTINCT FROM OLD.author_id OR NEW.pseudonym IS DISTINCT FROM OLD.pseudonym OR NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN RAISE EXCEPTION 'Protected fields'; END IF; END IF; RETURN NEW; END $$;
REVOKE SELECT ON public.messages, public.conversations, public.blocks, public.conversation_reads, public.reactions FROM authenticated, anon;
DROP POLICY IF EXISTS "participants view messages" ON public.messages;
CREATE POLICY "admins read messages" ON public.messages FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "participants view conversations" ON public.conversations;
CREATE POLICY "admins read conversations" ON public.conversations FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "anyone reads reactions" ON public.reactions;
CREATE POLICY "admins read reactions" ON public.reactions FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
REVOKE SELECT ON public.posts, public.comments FROM authenticated, anon;
GRANT SELECT (id,title,body,community,pseudonym,post_type,progress,created_at,expires_at,author_deleted,admin_removed,is_deleted) ON public.posts TO authenticated, anon;
GRANT SELECT (id,post_id,body,pseudonym,created_at,admin_removed,is_deleted) ON public.comments TO authenticated, anon;
DROP POLICY IF EXISTS "authors read own posts" ON public.posts;
DROP POLICY IF EXISTS "authors read own comments" ON public.comments;
DROP POLICY IF EXISTS "admins read all posts" ON public.posts;
DROP POLICY IF EXISTS "admins read all comments" ON public.comments;
CREATE POLICY "admins read all posts" ON public.posts FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
CREATE POLICY "admins read all comments" ON public.comments FOR SELECT TO authenticated USING (public.has_role(auth.uid(),'admin'));
DROP POLICY IF EXISTS "public reads visible posts" ON public.posts;
CREATE POLICY "public reads visible posts" ON public.posts FOR SELECT USING (NOT is_deleted AND NOT author_deleted AND NOT admin_removed AND (expires_at IS NULL OR expires_at > now()) AND (auth.uid() IS NULL OR NOT public.is_banned(auth.uid())));
DROP POLICY IF EXISTS "public reads visible comments" ON public.comments;
CREATE POLICY "public reads visible comments" ON public.comments FOR SELECT USING (NOT is_deleted AND NOT admin_removed AND (auth.uid() IS NULL OR NOT public.is_banned(auth.uid())));
DROP POLICY IF EXISTS "create reports" ON public.reports;
CREATE POLICY "create reports" ON public.reports FOR INSERT TO authenticated WITH CHECK (reporter_id=auth.uid() AND NOT public.is_banned(auth.uid()));